Writing the error boundary component now.

**src/components/ErrorBoundary.tsx**

```tsx
import { Component, ErrorInfo, ReactNode } from 'react';

interface Props {
  children: ReactNode;
  fallback?: (error: Error, reset: () => void) => ReactNode;
  onError?: (error: Error, info: ErrorInfo) => void;
}

interface State {
  error: Error | null;
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null };

  static getDerivedStateFromError(error: Error): State {
    return { error };
  }

  componentDidCatch(error: Error, info: ErrorInfo) {
    console.error('[ErrorBoundary]', error.message, {
      stack: error.stack,
      componentStack: info.componentStack,
    });
    this.props.onError?.(error, info);
  }

  reset = () => this.setState({ error: null });

  render() {
    const { error } = this.state;
    const { children, fallback } = this.props;

    if (!error) return children;

    if (fallback) return fallback(error, this.reset);

    return <DefaultFallback error={error} reset={this.reset} />;
  }
}

function DefaultFallback({ error, reset }: { error: Error; reset: () => void }) {
  return (
    <div role="alert" style={styles.container}>
      <h2 style={styles.title}>Something went wrong</h2>
      <pre style={styles.message}>{error.message}</pre>
      <button onClick={reset} style={styles.button}>
        Retry
      </button>
    </div>
  );
}

const styles = {
  container: {
    padding: '2rem',
    borderRadius: '8px',
    border: '1px solid #f87171',
    background: '#fef2f2',
    maxWidth: '480px',
    margin: '2rem auto',
    fontFamily: 'sans-serif',
  },
  title: { margin: '0 0 0.5rem', color: '#b91c1c', fontSize: '1.125rem' },
  message: {
    margin: '0 0 1rem',
    padding: '0.75rem',
    background: '#fee2e2',
    borderRadius: '4px',
    fontSize: '0.875rem',
    whiteSpace: 'pre-wrap' as const,
    wordBreak: 'break-word' as const,
    color: '#7f1d1d',
  },
  button: {
    padding: '0.5rem 1.25rem',
    background: '#dc2626',
    color: '#fff',
    border: 'none',
    borderRadius: '6px',
    cursor: 'pointer',
    fontSize: '0.875rem',
  },
} as const;
```

**Usage examples:**

```tsx
// Basic — uses default fallback UI
<ErrorBoundary>
  <MyComponent />
</ErrorBoundary>

// Custom fallback UI
<ErrorBoundary fallback={(error, retry) => (
  <div>
    <p>Oops: {error.message}</p>
    <button onClick={retry}>Try again</button>
  </div>
)}>
  <MyComponent />
</ErrorBoundary>

// With external error reporting (Sentry, Datadog, etc.)
<ErrorBoundary onError={(error, info) => Sentry.captureException(error, { extra: info })}>
  <MyComponent />
</ErrorBoundary>
```

Key design decisions:

- **`reset`** sets `error: null` — React re-mounts children fresh on next render.
- **`onError` prop** decouples logging from the component; the built-in `console.error` always runs, external reporters are opt-in.
- **`fallback` render prop** gives full control over the UI without subclassing.
- Class component is required — `getDerivedStateFromError` / `componentDidCatch` have no hook equivalents yet.
